const output = $('Lead Intelligence Agent').item.json.output;
const firstName = output.leadName.split(' ')[0];
const agencyName = output.agencyName;
const hours = output.totalHoursLostPerMonth;
const monthlyCost = output.totalCostPerMonth;

const dm = `Hi ${firstName}, ran a quick audit on ${agencyName} — found ${hours} hours your team is losing every month to manual processes. Comes out to around ${monthlyCost} a month.\n\nPut it into a report. Can I send it over?\n\nJust reply "yes."`;

return [{ json: { linkedInDM: dm, agencyName, firstName, hours, monthlyCost } }];
